I love the option for switching themes based on time; it would also be nice to have an option to switch on the day of the week. I think this would do it but I haven't tested it: 
```

use_theme_auto <- function(dark_start = "18:00", dark_end = "6:00",day = "Wednesday",
                           day_theme = "base16 Cupcake {rsthemes}" , quietly = FALSE) {
  dark_start <- hms::parse_hm(dark_start)
  dark_end <- hms::parse_hm(dark_end)
  now <- hms::as_hms(Sys.time())
  today<- weekdays(Sys.Date())
  pre_start <- use_theme_dark
  
  if (dark_end > dark_start) {
    # if light mode overnight, swap dark start/end
    .dark_start <- dark_start
    dark_start <- dark_end
    dark_end <- .dark_start
    pre_start <- use_theme_light
  }
  
  if (now > dark_start) {
    use_theme_dark(quietly)
  } else if (now > dark_end) {
    use_theme_light(quietly)
  } else {
    pre_start(quietly)
  }
  if (day == today) {
    use_theme_light(day_theme,quietly)
    else {
    pre_start(quietly)
  }
  
  } 
```
